	(3, 12, 24, 'Makanan keluarga yang dipotong kecil', '3-4 kali makan utama + 1-2 kali selingan', '3/4 hingga 1 mangkuk 250 ml', '2026-06-04 17:31:36.441687+00', '2026-06-04 17:31:36.441687+00', NULL);
INSERT INTO "public"."vaksin" ("id", "nama", "deskripsi", "efek_samping", "created_at", "updated_at", "deleted_at") VALUES
	(1, 'Hepatitis B', 'Mencegah penularan virus Hepatitis B dari ibu atau lingkungan.', 'Nyeri, kemerahan, atau bengkak ringan pada area suntikan.', NULL, NULL, NULL),
	(2, 'Bacillus Calmette-Guérin (BCG)', 'Mencegah penyakit tuberkulosis (TBC) berat, seperti meningitis TBC, terutama pada bayi.', 'Munculnya benjolan merah kecil, bisul, atau luka bernanah (ulserasi) di tempat suntikan, biasanya 2-12 minggu setelah divaksin.', NULL, NULL, NULL),
	(3, ' Polio Tetes', 'Membentuk antibodi dan memberikan perlindungan terhadap virus polio.', 'Demam ringan, rewel, nafsu makan menurun, serta gangguan pencernaan ringan seperti mual, muntah, atau diare.', NULL, NULL, NULL),
	(4, 'DPT-HB-Hib', 'Imunisasi kombinasi wajib untuk mencegah 6 penyakit serius pada anak: difteri, pertusis (batuk rejan), tetanus, hepatitis B, pneumonia, dan meningitis', 'Nyeri, bengkak, atau kemerahan di area suntikan dan demam ringan hingga tinggi', NULL, NULL, NULL),
	(5, 'IPV', 'Melindungi anak dari polio tipe 1, 2, dan 3 tanpa risiko menyebabkan penyakit', 'Nyeri, kemerahan, atau bengkak di lokasi suntikan, serta kemungkinan demam ringan', NULL, NULL, NULL),
	(6, 'MR (Campak Rubella)', 'Imunisasi wajib untuk melindungi anak dari penyakit campak dan rubella (campak Jerman) menggunakan virus yang dilemahkan', 'Demam ringan, nyeri di lokasi suntikan, atau ruam, yang biasanya muncul 5–14 hari setelah vaksinasi', NULL, NULL, NULL);
