INSERT INTO "public"."catatan_pelayanan" ("id", "anak_id", "tenaga_kesehatan_id", "tanggal_periksa", "tanggal_kembali", "catatan_pelayanan", "created_at", "updated_at", "deleted_at") VALUES
	(2, 20, 101, '2024-03-15 00:00:00+00', '2024-04-15 00:00:00+00', 'Ibu Duma khawatir berat badan anak naik terlalu cepat. Ditemukan riwayat pemberian susu kental manis secara rutin. Edukasi bahaya gula berlebih dan panduan diet gizi seimbang untuk balita.', '2026-06-09 20:03:21.988511+00', '2026-06-09 20:03:21.988511+00', NULL),
	(3, 21, 101, '2026-03-10 00:00:00+00', '2026-03-13 00:00:00+00', 'Anak BAB cair lebih dari 5 kali sehari, ampas sedikit. Anak tampak lemas, rewel, dan mata sedikit cekung. Diberikan oralit dan zinc, serta diedukasi untuk terus memberikan ASI lebih sering.', '2026-06-09 20:03:21.988511+00', '2026-06-09 20:03:21.988511+00', NULL),
	(4, 21, 101, '2026-04-10 00:00:00+00', '2026-04-17 00:00:00+00', 'Pemeriksaan pasca diare kronis bulan lalu. Berat badan anak merosot tajam. Anak tampak pasif. Rujuk segera ke RSUD terdekat untuk tata laksana gizi buruk (pemberian F-100).', '2026-06-09 20:03:21.988511+00', '2026-06-09 20:03:21.988511+00', NULL),
	(5, 1, 1, '0001-01-01 00:00:00+00', '0001-01-01 00:00:00+00', '', '2026-06-11 06:51:44.670943+00', '2026-06-11 06:51:44.670943+00', NULL),
	(1, 19, 101, '2022-05-10 00:00:00+00', '2022-05-17 00:00:00+00', 'Ibu mengeluh anak rewel, nafsu makan turun drastis dalam sebulan terakhir, dan sering batuk pilek. Disarankan pemberian PMT (Pemberian Makanan Tambahan) dan rujukan ke poli gizi puskesmas.', '2026-06-09 20:03:21.988511+00', '2026-06-11 06:53:37.8125+00', '2026-06-11 06:55:16.158301+00');
INSERT INTO "public"."catatan_pelayanan_kehamilan" ("id_catatan", "kehamilan_id", "trimester", "tanggal_periksa_stamp_paraf", "keluhan_pemeriksaan_tindakan_saran", "tanggal_kembali") VALUES
	(1, 1, 1, '2024-02-05', 'Keluhan: mual di pagi hari, nafsu makan berkurang. Pemeriksaan: TD 110/70 mmHg, BB 52 kg, TFU belum teraba. Tindakan: Diberikan vitamin B6 dan edukasi makan sedikit tapi sering.', '2024-03-05'),
	(2, 1, 1, '2024-03-07', 'Keluhan: pusing ringan saat bangun tidur. Pemeriksaan: TD 108/72 mmHg, BB 53 kg, Hb 11.2 g/dL. Tindakan: Diberikan tablet tambah darah dan disarankan istirahat cukup.', '2024-04-07'),
	(3, 1, 2, '2024-05-10', 'Keluhan: punggung terasa pegal, kaki sedikit bengkak. Pemeriksaan: TD 115/75 mmHg, BB 57 kg, TFU 20 cm, DJJ 140x/menit. Tindakan: Anjuran senam hamil dan batasi berdiri terlalu lama.', '2024-06-10'),
	(4, 1, 2, '2024-06-12', 'Keluhan: sering buang air kecil di malam hari. Pemeriksaan: TD 118/76 mmHg, BB 59 kg, TFU 24 cm, DJJ 144x/menit. Tindakan: Edukasi posisi tidur miring kiri, konsumsi air putih cukup siang hari.', '2024-07-12'),
	(5, 1, 3, '2024-08-20', 'Keluhan: sesak napas ringan saat berbaring, kontraksi palsu sesekali. Pemeriksaan: TD 120/80 mmHg, BB 64 kg, TFU 32 cm, DJJ 138x/menit, kepala sudah masuk PAP. Tindakan: Edukasi tanda-tanda persalinan, persiapkan perlengkapan melahirkan.', '2024-09-10');
INSERT INTO "public"."catatan_pelayanan_nifas" ("id_catatan_nifas", "kehamilan_id", "kunjungan_ke", "tanggal_periksa_stamp_paraf", "keluhan_pemeriksaan_tindakan_saran", "tanggal_kembali") VALUES
	(1, 1, '1', NULL, 'Ibu harus mulai memperhatikan makanan yang dikonsumsi', NULL),
	(2, 1, '2', '2026-06-03 08:47:54+00', 'Ibu haruss membiasakan diri untuk mengonsumsi buah buahan untuk memenuhi vitamin guna memproduksi asi dengan kuaalitas yang baik', NULL),
	(3, 10, 'KF1', '2026-06-09 00:00:00+00', 'sa', NULL),
	(5, 10, 'KF2', '2026-06-09 00:00:00+00', 'sa', NULL),
	(6, 10, 'KF3', '2026-06-09 00:00:00+00', 'asdfdgf', NULL),
	(110, 40, 'KF1', '2025-05-31 17:00:00+00', 'Ibu dalam kondisi baik pasca persalinan spontan. Kolostrum sudah keluar, bayi mulai menyusu. Luka perineum bersih.', '2025-06-07 17:00:00+00'),
	(111, 40, 'KF2', '2025-06-04 17:00:00+00', 'Ibu mengatakan sedikit lelah karena bayi sering menyusu di malam hari. Dijelaskan bahwa ini normal dan penting untuk produksi ASI. Suami dianjurkan membantu merawat bayi agar ibu cukup istirahat.', '2025-06-09 17:00:00+00'),
	(200, 8, 'KF3', '2026-06-10 00:00:00+00', 'Perlu banyak minum', NULL),
	(201, 8, 'KF3', '2026-06-10 00:00:00+00', 'Konsumsi makanan bergizi', NULL);
INSERT INTO "public"."kategori_trimester" ("id", "nama_trimester") VALUES
	(1, 'Trimester 1'),
	(2, 'Trimester 2'),
	(3, 'Trimester 3');
INSERT INTO "public"."catatan_pelayanan_trimester" ("id", "kehamilan_id", "tanggal_periksa_stamp_paraf", "keluhan_pemeriksaan_tindakan_saran", "tanggal_kembali", "kategori_trimester_id") VALUES
	(1, 1, '2025-06-15', 'Ibu mengeluh mual di pagi hari. Diberikan edukasi makan porsi kecil tapi sering, konsumsi jahe hangat. Anjurkan kunjungan ulang TM1 minggu ke-12.', '2025-07-13', 1),
	(2, 37, '2025-03-10', 'Ibu dalam kondisi baik, tidak ada keluhan berarti. Anjurkan konsumsi TTD tiap malam sebelum tidur.', '2025-04-14', 1),
	(3, 1, '2024-12-27', 'Tidak ada keluhan. IMT agak tinggi, anjurkan kontrol porsi makan dan aktivitas ringan seperti jalan pagi.', '2025-02-01', 1),
	(4, 39, '2024-12-30', 'Tensi 125/82, diberikan edukasi diet rendah garam dan kontrol berat badan secara rutin.', '2025-02-03', 1),
	(5, 1, '2026-06-02', 'Ibu harus memperhatikan pola tidurnya', '2026-06-04', 2),
	(6, 1, '2026-06-04', 'Ibu harus memperhatikan kondisi fisiknya', '2026-06-05', 2),
	(7, 37, '2025-05-31', 'Ibu merasa janin sudah mulai bergerak. Hb sedikit turun, dianjurkan makan makanan kaya zat besi (daun singkong, ikan). Tetap lanjutkan TTD setiap hari.', '2025-06-30', 2),
	(8, 38, '2025-03-07', 'Perkembangan janin baik. DJJ 145x/menit, TFU sesuai usia kehamilan.', '2025-04-11', 2),
	(9, 39, '2025-03-10', 'Tensi 128/85, masih dalam batas waspada. Anjurkan pantau TD mandiri di rumah tiap pagi.', '2025-04-07', 2),
	(10, 6, '2026-06-09', 'minum lebih banyak', NULL, 3),
	(11, 38, '2025-06-07', 'Ibu mengeluh sering kencing dan punggung pegal. Normal di TM3. Hb 10.8 (anemia ringan), tambahkan konsumsi TTD 2x/hari dan makanan tinggi zat besi. Anjurkan segera ke faskes bila ada tanda persalinan.', '2025-06-21', 3),
	(12, 39, '2025-06-09', 'Ibu mengeluh kepala terasa berat sejak 3 hari lalu. TD 138/90, proteinuria +1. Dirujuk ke dokter SpOG Puskesmas Pollung untuk evaluasi lebih lanjut. Pantau TD tiap hari, catat gerakan janin.', '2025-06-16', 3),
	(13, 40, '2025-05-23', 'Ibu dalam kondisi baik. Kepala bayi sudah masuk PAP. Anjurkan persiapan perlengkapan persalinan dan siapkan pendonor darah.', '2025-05-31', 3);
