INSERT INTO "public"."materi_mpasi" ("id", "judul", "konten", "gambar_url", "bulan_min", "bulan_max", "created_at", "updated_at", "deleted_at") VALUES
	(1, 'Memulai MPASI Usia 6 Bulan', 'MPASI mulai diberikan saat bayi berusia 6 bulan dengan tetap melanjutkan ASI. Mulailah dengan makanan lumat yang kaya zat besi dan protein hewani.', 'https://example.com/mpasi-6bulan.jpg', 6, 8, '2026-06-04 17:32:45.839927+00', '2026-06-04 17:32:45.839927+00', NULL),
	(2, 'Pentingnya Protein Hewani', 'Protein hewani seperti telur, ikan, ayam, hati ayam, dan daging penting untuk mendukung pertumbuhan optimal dan mencegah stunting.', 'https://example.com/protein-hewani.jpg', 6, 24, '2026-06-04 17:32:45.839927+00', '2026-06-04 17:32:45.839927+00', NULL),
	(3, 'Tanda Bayi Siap MPASI', 'Bayi mampu duduk dengan bantuan, tertarik pada makanan, dan refleks menjulurkan lidah mulai berkurang.', 'https://example.com/siap-mpasi.jpg', 6, 6, '2026-06-04 17:32:45.839927+00', '2026-06-04 17:32:45.839927+00', NULL),
	(4, 'Pencegahan Stunting Melalui MPASI', 'MPASI harus mengandung karbohidrat, protein hewani, sayur, buah, dan lemak sehat untuk memenuhi kebutuhan gizi anak.', 'https://example.com/cegah-stunting.jpg', 6, 24, '2026-06-04 17:32:45.839927+00', '2026-06-04 17:32:45.839927+00', NULL),
	(5, 'Prinsip Isi Piring MPASI', 'Setiap porsi MPASI idealnya terdiri dari sumber karbohidrat, protein hewani, protein nabati, sayur, dan lemak tambahan.', 'https://example.com/isi-piring.jpg', 6, 24, '2026-06-04 17:32:45.839927+00', '2026-06-04 17:32:45.839927+00', NULL),
